-- ============================================================================
-- 0028_magic_items_tokens_part1of2.sql
--
-- Full SRD 5.1 magic items (237, CC-BY-4.0) as 'item' tokens with full
-- details + first-letter monogram placeholder art (/icons/items/_mono/<L>.svg).
-- Run both parts, any order. Idempotent: skips an item you already have by name.
-- Attribution: D&D 5.1 SRD, CC-BY-4.0 (see details.source).
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, details)
  select me, v.name, v.image_url, 'item', 'medium',
         jsonb_build_object('kind','item','item', v.item::jsonb)
  from (values
    ('Adamantine Armor', '/icons/items/_mono/A.svg', '{"name":"Adamantine Armor","itemType":"Armor","rarity":"uncommon","description":"This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you''re wearing it, any critical hit against you becomes a normal hit.","source":"SRD 5.1, CC-BY-4.0","baseType":"medium or heavy"}'),
    ('Amulet of Health', '/icons/items/_mono/A.svg', '{"name":"Amulet of Health","itemType":"Wondrous item","rarity":"rare","description":"Your Constitution score is 19 while you wear this amulet. It has no effect on you if your Constitution is already 19 or higher.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Amulet of Proof against Detection and Location', '/icons/items/_mono/A.svg', '{"name":"Amulet of Proof against Detection and Location","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this amulet, you are hidden from divination magic. You can''t be targeted by such magic or perceived through magical scrying sensors.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Amulet of the Planes', '/icons/items/_mono/A.svg', '{"name":"Amulet of the Planes","itemType":"Wondrous item","rarity":"very rare","description":"While wearing this amulet, you can use an action to name a location that you are familiar with on another plane of existence. Then make a DC 15 Intelligence check. On a successful check, you cast the _plane shift_ spell. On a failure, you and each creature and object within 15 feet of you travel to a random destination. Roll a d100. On a 1-60, you travel to a random location on the plane you named. On a 61-100, you travel to a randomly determined plane of existence.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Animated Shield', '/icons/items/_mono/A.svg', '{"name":"Animated Shield","itemType":"Armor","rarity":"very rare","description":"While holding this shield, you can speak its command word as a bonus action to cause it to animate. The shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free. The shield remains animated for 1 minute, until you use a bonus action to end this effect, or until you are incapacitated or die, at which point the shield falls to the ground or into your hand if you have one free.","source":"SRD 5.1, CC-BY-4.0","baseType":"shield","attunement":true}'),
    ('Apparatus of the Crab', '/icons/items/_mono/A.svg', '{"name":"Apparatus of the Crab","itemType":"Wondrous item","rarity":"legendary","description":"This item first appears to be a Large sealed iron barrel weighing 500 pounds. The barrel has a hidden catch, which can be found with a successful DC 20 Intelligence (Investigation) check. Releasing the catch unlocks a hatch at one end of the barrel, allowing two Medium or smaller creatures to crawl inside. Ten levers are set in a row at the far end, each in a neutral position, able to move either up or down. When certain levers are used, the apparatus transforms to resemble a giant lobster.\n\nThe apparatus of the Crab is a Large object with the following statistics:\n\n**Armor Class:** 20\n\n**Hit Points:** 200\n\n**Speed:** 30 ft., swim 30 ft. (or 0 ft. for both if the legs and tail aren''t extended)\n\n**Damage Immunities:** poison, psychic\n\nTo be used as a vehicle, the apparatus requires one pilot. While the apparatus''s hatch is closed, the compartment is airtight and watertight. The compartment holds enough air for 10 hours of breathing, divided by the number of breathing creatures inside.\n\nThe apparatus floats on water. It can also go underwater to a depth of 900 feet. Below that, the vehicle takes 2d6 bludgeoning damage per minute from pressure.\n\nA creature in the compartment can use an action to move as many as two of the apparatus''s levers up or down. After each use, a lever goes back to its neutral position. Each lever, from left to right, functions as shown in the Apparatus of the Crab Levers table.\n\n**Apparatus of the Crab Levers (table)**\n\n| Lever | Up                                                                                                                               | Down                                                                                                                                        |\n|-------|----------------------------------------------------------------------------------------------------------------------------------|---------------------------------------------------------------------------------------------------------------------------------------------|\n| 1     | Legs and tail extend, allowing the apparatus to walk and swim.                                                                   | Legs and tail retract, reducing the apparatus''s speed to 0 and making it unable to benefit from bonuses to speed.                           |\n| 2     | Forward window shutter opens.                                                                                                    | Forward window shutter closes.                                                                                                              |\n| 3     | Side window shutters open (two per side).                                                                                        | Side window shutters close (two per side).                                                                                                  |\n| 4     | Two claws extend from the front sides of the apparatus.                                                                          | The claws retract.                                                                                                                          |\n| 5     | Each extended claw makes the following melee weapon attack: +8 to hit, reach 5 ft., one target. Hit: 7 (2d6) bludgeoning damage. | Each extended claw makes the following melee weapon attack: +8 to hit, reach 5 ft., one target. Hit: The target is grappled (escape DC 15). |\n| 6     | The apparatus walks or swims forward.                                                                                            | The apparatus walks or swims backward.                                                                                                      |\n| 7     | The apparatus turns 90 degrees left.                                                                                             | The apparatus turns 90 degrees right.                                                                                                       |\n| 8     | Eyelike fixtures emit bright light in a 30-foot radius and dim light for an additional 30 feet.                                  | The light turns off.                                                                                                                        |\n| 9     | The apparatus sinks as much as 20 feet in liquid.                                                                                | The apparatus rises up to 20 feet in liquid.                                                                                                |\n| 10    | The rear hatch unseals and opens.                                                                                                | The rear hatch closes and seals.                                                                                                            |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Armor of Invulnerability', '/icons/items/_mono/A.svg', '{"name":"Armor of Invulnerability","itemType":"Armor","rarity":"legendary","description":"You have resistance to nonmagical damage while you wear this armor. Additionally, you can use an action to make yourself immune to nonmagical damage for 10 minutes or until you are no longer wearing the armor. Once this special action is used, it can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","baseType":"plate","attunement":true}'),
    ('Armor of Resistance', '/icons/items/_mono/A.svg', '{"name":"Armor of Resistance","itemType":"Armor","rarity":"rare","description":"You have resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly from the options below.\n\n| d10 | Damage Type |\n|-----|-------------|\n| 1   | Acid        |\n| 2   | Cold        |\n| 3   | Fire        |\n| 4   | Force       |\n| 5   | Lightning   |\n| 6   | Necrotic    |\n| 7   | Poison      |\n| 8   | Psychic     |\n| 9   | Radiant     |\n| 10  | Thunder     |","source":"SRD 5.1, CC-BY-4.0","baseType":"light","attunement":true}'),
    ('Armor of Vulnerability', '/icons/items/_mono/A.svg', '{"name":"Armor of Vulnerability","itemType":"Armor","rarity":"rare","description":"While wearing this armor, you have resistance to one of the following damage types: bludgeoning, piercing, or slashing. The GM chooses the type or determines it randomly.\n\n**_Curse_**. This armor is cursed, a fact that is revealed only when an _identify_ spell is cast on the armor or you attune to it. Attuning to the armor curses you until you are targeted by the _remove curse_ spell or similar magic; removing the armor fails to end the curse. While cursed, you have vulnerability to two of the three damage types associated with the armor (not the one to which it grants resistance).","source":"SRD 5.1, CC-BY-4.0","baseType":"plate","attunement":true}'),
    ('Arrow of Slaying', '/icons/items/_mono/A.svg', '{"name":"Arrow of Slaying","itemType":"Weapon","rarity":"very rare","description":"An _arrow of slaying_ is a magic weapon meant to slay a particular kind of creature. Some are more focused than others; for example, there are both _arrows of dragon slaying_ and _arrows of blue dragon slaying_. If a creature belonging to the type, race, or group associated with an _arrow of slaying_ takes damage from the arrow, the creature must make a DC 17 Constitution saving throw, taking an extra 6d10 piercing damage on a failed save, or half as much extra damage on a successful one.\n\nOnce an _arrow of slaying_ deals its extra damage to a creature, it becomes a nonmagical arrow.\n\nOther types of magic ammunition of this kind exist, such as _bolts of slaying_ meant for a crossbow, though arrows are most common.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"arrow"}'),
    ('Arrow-Catching Shield', '/icons/items/_mono/A.svg', '{"name":"Arrow-Catching Shield","itemType":"Armor","rarity":"rare","description":"You gain a +2 bonus to AC against ranged attacks while you wield this shield. This bonus is in addition to the shield''s normal bonus to AC. In addition, whenever an attacker makes a ranged attack against a target within 5 feet of you, you can use your reaction to become the target of the attack instead.","source":"SRD 5.1, CC-BY-4.0","baseType":"shield","attunement":true}'),
    ('Bag of Beans', '/icons/items/_mono/B.svg', '{"name":"Bag of Beans","itemType":"Wondrous item","rarity":"rare","description":"Inside this heavy cloth bag are 3d4 dry beans. The bag weighs 1/2 pound plus 1/4 pound for each bean it contains.\n\nIf you dump the bag''s contents out on the ground, they explode in a 10-foot radius, extending from the beans. Each creature in the area, including you, must make a DC 15 Dexterity saving throw, taking 5d4 fire damage on a failed save, or half as much damage on a successful one. The fire ignites flammable objects in the area that aren''t being worn or carried.\n\nIf you remove a bean from the bag, plant it in dirt or sand, and then water it, the bean produces an effect 1 minute later from the ground where it was planted. The GM can choose an effect from the following table, determine it randomly, or create an effect.\n\n| d100  | Effect                                                                                                                                                                                                                                                                                                                                                                |\n|-------|-----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| 01    | 5d4 toadstools sprout. If a creature eats a toadstool, roll any die. On an odd roll, the eater must succeed on a DC 15 Constitution saving throw or take 5d6 poison damage and become poisoned for 1 hour. On an even roll, the eater gains 5d6 temporary hit points for 1 hour.                                                                                      |\n| 02-10 | A geyser erupts and spouts water, beer, berry juice, tea, vinegar, wine, or oil (GM''s choice) 30 feet into the air for 1d12 rounds.                                                                                                                                                                                                                                   |\n| 11-20 | A treant sprouts. There''s a 50 percent chance that the treant is chaotic evil and attacks.                                                                                                                                                                                                                                                                            |\n| 21-30 | An animate, immobile stone statue in your likeness rises. It makes verbal threats against you. If you leave it and others come near, it describes you as the most heinous of villains and directs the newcomers to find and attack you. If you are on the same plane of existence as the statue, it knows where you are. The statue becomes inanimate after 24 hours. |\n| 31-40 | A campfire with blue flames springs forth and burns for 24 hours (or until it is extinguished).                                                                                                                                                                                                                                                                       |\n| 41-50 | 1d6 + 6 shriekers sprout                                                                                                                                                                                                                                                                                                                                              |\n| 51-60 | 1d4 + 8 bright pink toads crawl forth. Whenever a toad is touched, it transforms into a Large or smaller monster of the GM''s choice. The monster remains for 1 minute, then disappears in a puff of bright pink smoke.                                                                                                                                                |\n| 61-70 | A hungry bulette burrows up and attacks. 71-80 A fruit tree grows. It has 1d10 + 20 fruit, 1d8 of which act as randomly determined magic potions, while one acts as an ingested poison of the GM''s choice. The tree vanishes after 1 hour. Picked fruit remains, retaining any magic for 30 days.                                                                     |\n| 81-90 | A nest of 1d4 + 3 eggs springs up. Any creature that eats an egg must make a DC 20 Constitution saving throw. On a successful save, a creature permanently increases its lowest ability score by 1, randomly choosing among equally low scores. On a failed save, the creature takes 10d6 force damage from an internal magical explosion.                            |\n| 91-99 | A pyramid with a 60-foot-square base bursts upward. Inside is a sarcophagus containing a mummy lord. The pyramid is treated as the mummy lord''s lair, and its sarcophagus contains treasure of the GM''s choice.                                                                                                                                                       |\n| 100   | A giant beanstalk sprouts, growing to a height of the GM''s choice. The top leads where the GM chooses, such as to a great view, a cloud giant''s castle, or a different plane of existence.                                                                                                                                                                            |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Bag of Devouring', '/icons/items/_mono/B.svg', '{"name":"Bag of Devouring","itemType":"Wondrous item","rarity":"very rare","description":"This bag superficially resembles a _bag of holding_ but is a feeding orifice for a gigantic extradimensional creature. Turning the bag inside out closes the orifice.\n\nThe extradimensional creature attached to the bag can sense whatever is placed inside the bag. Animal or vegetable matter placed wholly in the bag is devoured and lost forever. When part of a living creature is placed in the bag, as happens when someone reaches inside it, there is a 50 percent chance that the creature is pulled inside the bag. A creature inside the bag can use its action to try to escape with a successful DC 15 Strength check. Another creature can use its action to reach into the bag to pull a creature out, doing so with a successful DC 20 Strength check (provided it isn''t pulled inside the bag first). Any creature that starts its turn inside the bag is devoured, its body destroyed.\n\nInanimate objects can be stored in the bag, which can hold a cubic foot of such material. However, once each day, the bag swallows any objects inside it and spits them out into another plane of existence. The GM determines the time and plane.\n\nIf the bag is pierced or torn, it is destroyed, and anything contained within it is transported to a random location on the Astral Plane.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Bag of Holding', '/icons/items/_mono/B.svg', '{"name":"Bag of Holding","itemType":"Wondrous item","rarity":"uncommon","description":"This bag has an interior space considerably larger than its outside dimensions, roughly 2 feet in diameter at the mouth and 4 feet deep. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 15 pounds, regardless of its contents. Retrieving an item from the bag requires an action.\n\nIf the bag is overloaded, pierced, or torn, it ruptures and is destroyed, and its contents are scattered in the Astral Plane. If the bag is turned inside out, its contents spill forth, unharmed, but the bag must be put right before it can be used again. Breathing creatures inside the bag can survive up to a number of minutes equal to 10 divided by the number of creatures (minimum 1 minute), after which time they begin to suffocate.\n\nPlacing a _bag of holding_ inside an extradimensional space created by a _handy haversack_, _portable hole_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way only and can''t be reopened.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Bag of Tricks', '/icons/items/_mono/B.svg', '{"name":"Bag of Tricks","itemType":"Wondrous item","rarity":"uncommon","description":"This ordinary bag, made from gray, rust, or tan cloth, appears empty. Reaching inside the bag, however, reveals the presence of a small, fuzzy object. The bag weighs 1/2 pound.\n\nYou can use an action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a creature you determine by rolling a d8 and consulting the table that corresponds to the bag''s color.\n\nThe creature is friendly to you and your companions, and it acts on your turn. You can use a bonus action to command how the creature moves and what action it takes on its next turn, or to give it general orders, such as to attack your enemies. In the absence of such orders, the creature acts in a fashion appropriate to its nature.\n\nOnce three fuzzy objects have been pulled from the bag, the bag can''t be used again until the next dawn.\n\n**Gray Bag of Tricks (table)**\n\n| d8 | Creature     |\n|----|--------------|\n| 1  | Weasel       |\n| 2  | Giant rat    |\n| 3  | Badger       |\n| 4  | Boar         |\n| 5  | Panther      |\n| 6  | Giant badger |\n| 7  | Dire wolf    |\n| 8  | Giant elk    |\n\n**Rust Bag of Tricks (table)**\n\n| d8 | Creature   |\n|----|------------|\n| 1  | Rat        |\n| 2  | Owl        |\n| 3  | Mastiff    |\n| 4  | Goat       |\n| 5  | Giant goat |\n| 6  | Giant boar |\n| 7  | Lion       |\n| 8  | Brown bear |\n\n**Tan Bag of Tricks (table)**\n\n| d8 | Creature     |\n|----|--------------|\n| 1  | Jackal       |\n| 2  | Ape          |\n| 3  | Baboon       |\n| 4  | Axe beak     |\n| 5  | Black bear   |\n| 6  | Giant weasel |\n| 7  | Giant hyena  |\n| 8  | Tiger        |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Bead of Force', '/icons/items/_mono/B.svg', '{"name":"Bead of Force","itemType":"Wondrous item","rarity":"rare","description":"This small black sphere measures 3/4 of an inch in diameter and weighs an ounce. Typically, 1d4 + 4 _beads of force_ are found together.\n\nYou can use an action to throw the bead up to 60 feet. The bead explodes on impact and is destroyed. Each creature within a 10-foot radius of where the bead landed must succeed on a DC 15 Dexterity saving throw or take 5d4 force damage. A sphere of transparent force then encloses the area for 1 minute. Any creature that failed the save and is completely within the area is trapped inside this sphere. Creatures that succeeded on the save, or are partially within the area, are pushed away from the center of the sphere until they are no longer inside it. Only breathable air can pass through the sphere''s wall. No attack or other effect can.\n\nAn enclosed creature can use its action to push against the sphere''s wall, moving the sphere up to half the creature''s walking speed. The sphere can be picked up, and its magic causes it to weigh only 1 pound, regardless of the weight of creatures inside.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Belt of Dwarvenkind', '/icons/items/_mono/B.svg', '{"name":"Belt of Dwarvenkind","itemType":"Wondrous item","rarity":"rare","description":"While wearing this belt, you gain the following benefits:\n\n* Your Constitution score increases by 2, to a maximum of 20.\n* You have advantage on Charisma (Persuasion) checks made to interact with dwarves.\n\nIn addition, while attuned to the belt, you have a 50 percent chance each day at dawn of growing a full beard if you''re capable of growing one, or a visibly thicker beard if you already have one.\n\nIf you aren''t a dwarf, you gain the following additional benefits while wearing the belt:\n\n* You have advantage on saving throws against poison, and you have resistance against poison damage.\n* You have darkvision out to a range of 60 feet.\n* You can speak, read, and write Dwarvish.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Belt of Giant Strength', '/icons/items/_mono/B.svg', '{"name":"Belt of Giant Strength","itemType":"Wondrous item","rarity":"rare","description":"While wearing this belt, your Strength score changes to a score granted by the belt. If your Strength is already equal to or greater than the belt''s score, the item has no effect on you.\n\nSix varieties of this belt exist, corresponding with and having rarity according to the six kinds of true giants. The _belt of stone giant strength_ and the _belt of frost giant strength_ look different, but they have the same effect.\n\n| Type              | Strength | Rarity    |\n|-------------------|----------|-----------|\n| Hill giant        | 21       | Rare      |\n| Stone/frost giant | 23       | Very rare |\n| Fire giant        | 25       | Very rare |\n| Cloud giant       | 27       | Legendary |\n| Storm giant       | 29       | Legendary |","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Berserker Axe', '/icons/items/_mono/B.svg', '{"name":"Berserker Axe","itemType":"Weapon","rarity":"rare","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your hit point maximum increases by 1 for each level you have attained.\n\n**_Curse_**. This axe is cursed, and becoming attuned to it extends the curse to you. As long as you remain cursed, you are unwilling to part with the axe, keeping it within reach at all times. You also have disadvantage on attack rolls with weapons other than this one, unless no foe is within 60 feet of you that you can see or hear.\n\nWhenever a hostile creature damages you while the axe is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk. While berserk, you must use your action each round to attack the creature nearest to you with the axe. If you can make extra attacks as part of the Attack action, you use those extra attacks, moving to attack the next nearest creature after you fell your current target. If you have multiple possible targets, you attack one at random. You are berserk until you start your turn with no creatures within 60 feet of you that you can see or hear.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any axe","attunement":true}'),
    ('Boots of Elvenkind', '/icons/items/_mono/B.svg', '{"name":"Boots of Elvenkind","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have advantage on Dexterity (Stealth) checks that rely on moving silently.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Boots of Levitation', '/icons/items/_mono/B.svg', '{"name":"Boots of Levitation","itemType":"Wondrous item","rarity":"rare","description":"While you wear these boots, you can use an action to cast the _levitate_ spell on yourself at will.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Boots of Speed', '/icons/items/_mono/B.svg', '{"name":"Boots of Speed","itemType":"Wondrous item","rarity":"rare","description":"While you wear these boots, you can use a bonus action and click the boots'' heels together. If you do, the boots double your walking speed, and any creature that makes an opportunity attack against you has disadvantage on the attack roll. If you click your heels together again, you end the effect.\n\nWhen the boots'' property has been used for a total of 10 minutes, the magic ceases to function until you finish a long rest.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Boots of Striding and Springing', '/icons/items/_mono/B.svg', '{"name":"Boots of Striding and Springing","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear these boots, your walking speed becomes 30 feet, unless your walking speed is higher, and your speed isn''t reduced if you are encumbered or wearing heavy armor. In addition, you can jump three times the normal distance, though you can''t jump farther than your remaining movement would allow.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Boots of the Winterlands', '/icons/items/_mono/B.svg', '{"name":"Boots of the Winterlands","itemType":"Wondrous item","rarity":"uncommon","description":"These furred boots are snug and feel quite warm. While you wear them, you gain the following benefits:\n\n* You have resistance to cold damage.\n* You ignore difficult terrain created by ice or snow.\n* You can tolerate temperatures as low as -50 degrees Fahrenheit without any additional protection. If you wear heavy clothes, you can tolerate temperatures as low as -100 degrees Fahrenheit.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Bowl of Commanding Water Elementals', '/icons/items/_mono/B.svg', '{"name":"Bowl of Commanding Water Elementals","itemType":"Wondrous item","rarity":"rare","description":"While this bowl is filled with water, you can use an action to speak the bowl''s command word and summon a water elemental, as if you had cast the _conjure elemental_ spell. The bowl can''t be used this way again until the next dawn.\n\nThe bowl is about 1 foot in diameter and half as deep. It weighs 3 pounds and holds about 3 gallons.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Bracers of Archery', '/icons/items/_mono/B.svg', '{"name":"Bracers of Archery","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing these bracers, you have proficiency with the longbow and shortbow, and you gain a +2 bonus to damage rolls on ranged attacks made with such weapons.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Bracers of Defense', '/icons/items/_mono/B.svg', '{"name":"Bracers of Defense","itemType":"Wondrous item","rarity":"rare","description":"While wearing these bracers, you gain a +2 bonus to AC if you are wearing no armor and using no shield.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Brazier of Commanding Fire Elementals', '/icons/items/_mono/B.svg', '{"name":"Brazier of Commanding Fire Elementals","itemType":"Wondrous item","rarity":"rare","description":"While a fire burns in this brass brazier, you can use an action to speak the brazier''s command word and summon a fire elemental, as if you had cast the _conjure elemental_ spell. The brazier can''t be used this way again until the next dawn.\n\nThe brazier weighs 5 pounds.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Brooch of Shielding', '/icons/items/_mono/B.svg', '{"name":"Brooch of Shielding","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this brooch, you have resistance to force damage, and you have immunity to damage from the _magic missile_ spell.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Broom of Flying', '/icons/items/_mono/B.svg', '{"name":"Broom of Flying","itemType":"Wondrous item","rarity":"uncommon","description":"This wooden broom, which weighs 3 pounds, functions like a mundane broom until you stand astride it and speak its command word. It then hovers beneath you and can be ridden in the air. It has a flying speed of 50 feet. It can carry up to 400 pounds, but its flying speed becomes 30 feet while carrying over 200 pounds. The broom stops hovering when you land.\n\nYou can send the broom to travel alone to a destination within 1 mile of you if you speak the command word, name the location, and are familiar with that place. The broom comes back to you when you speak another command word, provided that the broom is still within 1 mile of you.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Candle of Invocation', '/icons/items/_mono/C.svg', '{"name":"Candle of Invocation","itemType":"Wondrous item","rarity":"very rare","description":"This slender taper is dedicated to a deity and shares that deity''s alignment. The candle''s alignment can be detected with the _detect evil and good_ spell. The GM chooses the god and associated alignment or determines the alignment randomly.\n\n| d20   | Alignment       |\n|-------|-----------------|\n| 1-2   | Chaotic evil    |\n| 3-4   | Chaotic neutral |\n| 5-7   | Chaotic good    |\n| 8-9   | Neutral evil    |\n| 10-11 | Neutral         |\n| 12-13 | Neutral good    |\n| 14-15 | Lawful evil     |\n| 16-17 | Lawful neutral  |\n| 18-20 | Lawful good     |\n\nThe candle''s magic is activated when the candle is lit, which requires an action. After burning for 4 hours, the candle is destroyed. You can snuff it out early for use at a later time. Deduct the time it burned in increments of 1 minute from the candle''s total burn time.\n\nWhile lit, the candle sheds dim light in a 30-foot radius. Any creature within that light whose alignment matches that of the candle makes attack rolls, saving throws, and ability checks with advantage. In addition, a cleric or druid in the light whose alignment matches the candle''s can cast 1st* level spells he or she has prepared without expending spell slots, though the spell''s effect is as if cast with a 1st-level slot.\n\nAlternatively, when you light the candle for the first time, you can cast the _gate_ spell with it. Doing so destroys the candle.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cape of the Mountebank', '/icons/items/_mono/C.svg', '{"name":"Cape of the Mountebank","itemType":"Wondrous item","rarity":"rare","description":"This cape smells faintly of brimstone. While wearing it, you can use it to cast the _dimension door_ spell as an action. This property of the cape can''t be used again until the next dawn.\n\nWhen you disappear, you leave behind a cloud of smoke, and you appear in a similar cloud of smoke at your destination. The smoke lightly obscures the space you left and the space you appear in, and it dissipates at the end of your next turn. A light or stronger wind disperses the smoke.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Carpet of Flying', '/icons/items/_mono/C.svg', '{"name":"Carpet of Flying","itemType":"Wondrous item","rarity":"very rare","description":"You can speak the carpet''s command word as an action to make the carpet hover and fly. It moves according to your spoken directions, provided that you are within 30 feet of it.\n\nFour sizes of _carpet of flying_ exist. The GM chooses the size of a given carpet or determines it randomly.\n\n| d100   | Size          | Capacity | Flying Speed |\n|--------|---------------|----------|--------------|\n| 01-20  | 3 ft. × 5 ft. | 200 lb.  | 80 feet      |\n| 21-55  | 4 ft. × 6 ft. | 400 lb.  | 60 feet      |\n| 56-80  | 5 ft. × 7 ft. | 600 lb.  | 40 feet      |\n| 81-100 | 6 ft. × 9 ft. | 800 lb.  | 30 feet      |\n\nA carpet can carry up to twice the weight shown on the table, but it flies at half speed if it carries more than its normal capacity.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Censer of Controlling Air Elementals', '/icons/items/_mono/C.svg', '{"name":"Censer of Controlling Air Elementals","itemType":"Wondrous item","rarity":"rare","description":"While incense is burning in this censer, you can use an action to speak the censer''s command word and summon an air elemental, as if you had cast the _conjure elemental_ spell. The censer can''t be used this way again until the next dawn.\n\nThis 6-inch-wide, 1-foot-high vessel resembles a chalice with a decorated lid. It weighs 1 pound.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Chime of Opening', '/icons/items/_mono/C.svg', '{"name":"Chime of Opening","itemType":"Wondrous item","rarity":"rare","description":"This hollow metal tube measures about 1 foot long and weighs 1 pound. You can strike it as an action, pointing it at an object within 120 feet of you that can be opened, such as a door, lid, or lock. The chime issues a clear tone, and one lock or latch on the object opens unless the sound can''t reach the object. If no locks or latches remain, the object itself opens.\n\nThe chime can be used ten times. After the tenth time, it cracks and becomes useless.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Circlet of Blasting', '/icons/items/_mono/C.svg', '{"name":"Circlet of Blasting","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this circlet, you can use an action to cast the _scorching ray_ spell with it. When you make the spell''s attacks, you do so with an attack bonus of +5. The circlet can''t be used this way again until the next dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Cloak of Arachnida', '/icons/items/_mono/C.svg', '{"name":"Cloak of Arachnida","itemType":"Wondrous item","rarity":"very rare","description":"This fine garment is made of black silk interwoven with faint silvery threads. While wearing it, you gain the following benefits:\n\n* You have resistance to poison damage.\n* You have a climbing speed equal to your walking speed.\n* You can move up, down, and across vertical surfaces and upside down along ceilings, while leaving your hands free.\n* You can''t be caught in webs of any sort and can move through webs as if they were difficult terrain.\n* You can use an action to cast the _web_ spell (save DC 13). The web created by the spell fills twice its normal area. Once used, this property of the cloak can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cloak of Displacement', '/icons/items/_mono/C.svg', '{"name":"Cloak of Displacement","itemType":"Wondrous item","rarity":"rare","description":"While you wear this cloak, it projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have disadvantage on attack rolls against you. If you take damage, the property ceases to function until the start of your next turn. This property is suppressed while you are incapacitated, restrained, or otherwise unable to move.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cloak of Elvenkind', '/icons/items/_mono/C.svg', '{"name":"Cloak of Elvenkind","itemType":"Wondrous item","rarity":"uncommon","description":"While you wear this cloak with its hood up, Wisdom (Perception) checks made to see you have disadvantage, and you have advantage on Dexterity (Stealth) checks made to hide, as the cloak''s color shifts to camouflage you. Pulling the hood up or down requires an action.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cloak of Protection', '/icons/items/_mono/C.svg', '{"name":"Cloak of Protection","itemType":"Wondrous item","rarity":"uncommon","description":"You gain a +1 bonus to AC and saving throws while you wear this cloak.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cloak of the Bat', '/icons/items/_mono/C.svg', '{"name":"Cloak of the Bat","itemType":"Wondrous item","rarity":"rare","description":"While wearing this cloak, you have advantage on Dexterity (Stealth) checks. In an area of dim light or darkness, you can grip the edges of the cloak with both hands and use it to fly at a speed of 40 feet. If you ever fail to grip the cloak''s edges while flying in this way, or if you are no longer in dim light or darkness, you lose this flying speed.\n\nWhile wearing the cloak in an area of dim light or darkness, you can use your action to cast _polymorph_ on yourself, transforming into a bat. While you are in the form of the bat, you retain your Intelligence, Wisdom, and Charisma scores. The cloak can''t be used this way again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cloak of the Manta Ray', '/icons/items/_mono/C.svg', '{"name":"Cloak of the Manta Ray","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this cloak with its hood up, you can breathe underwater, and you have a swimming speed of 60 feet. Pulling the hood up or down requires an action.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Crystal Ball', '/icons/items/_mono/C.svg', '{"name":"Crystal Ball","itemType":"Wondrous item","rarity":"very rare","description":"The typical _crystal ball_, a very rare item, is about 6 inches in diameter. While touching it, you can cast the _scrying_ spell (save DC 17) with it.\n\nThe following _crystal ball_ variants are legendary items and have additional properties.\n\n**_Crystal Ball of Mind Reading_**. You can use an action to cast the _detect thoughts_ spell (save DC 17) while you are scrying with the _crystal ball_, targeting creatures you can see within 30 feet of the spell''s sensor. You don''t need to concentrate on this _detect thoughts_ to maintain it during its duration, but it ends if _scrying_ ends.\n\n**_Crystal Ball of Telepathy_**. While scrying with the crystal ball, you can communicate telepathically with creatures you can see within 30 feet of the spell''s sensor. You can also use an action to cast the _suggestion_ spell (save DC 17) through the sensor on one of those creatures. You don''t need to concentrate on this _suggestion_ to maintain it during its duration, but it ends if _scrying_ ends. Once used, the _suggestion_ power of the _crystal ball_ can''t be used again until the next dawn.\n\n**_Crystal Ball of True Seeing_**. While scrying with the crystal ball, you have truesight with a radius of 120 feet centered on the spell''s sensor.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cube of Force', '/icons/items/_mono/C.svg', '{"name":"Cube of Force","itemType":"Wondrous item","rarity":"rare","description":"This cube is about an inch across. Each face has a distinct marking on it that can be pressed. The cube starts with 36 charges, and it regains 1d20 expended charges daily at dawn.\n\nYou can use an action to press one of the cube''s faces, expending a number of charges based on the chosen face, as shown in the Cube of Force Faces table. Each face has a different effect. If the cube has insufficient charges remaining, nothing happens. Otherwise, a barrier of invisible force springs into existence, forming a cube 15 feet on a side. The barrier is centered on you, moves with you, and lasts for 1 minute, until you use an action to press the cube''s sixth face, or the cube runs out of charges. You can change the barrier''s effect by pressing a different face of the cube and expending the requisite number of charges, resetting the duration.\n\nIf your movement causes the barrier to come into contact with a solid object that can''t pass through the cube, you can''t move any closer to that object as long as the barrier remains.\n\n**Cube of Force Faces (table)**\n\n| Face | Charges | Effect                                                                                                            |\n|------|---------|-------------------------------------------------------------------------------------------------------------------|\n| 1    | 1       | Gases, wind, and fog can''t pass through the barrier.                                                              |\n| 2    | 2       | Nonliving matter can''t pass through the barrier. Walls, floors, and ceilings can pass through at your discretion. |\n| 3    | 3       | Living matter can''t pass through the barrier.                                                                     |\n| 4    | 4       | Spell effects can''t pass through the barrier.                                                                     |\n| 5    | 5       | Nothing can pass through the barrier. Walls, floors, and ceilings can pass through at your discretion.            |\n| 6    | 0       | The barrier deactivates.                                                                                          |\n\nThe cube loses charges when the barrier is targeted by certain spells or comes into contact with certain spell or magic item effects, as shown in the table below.\n\n| Spell or Item    | Charges Lost |\n|------------------|--------------|\n| Disintegrate     | 1d12         |\n| Horn of blasting | 1d10         |\n| Passwall         | 1d6          |\n| Prismatic spray  | 1d20         |\n| Wall of fire     | 1d4          |","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Cubic Gate', '/icons/items/_mono/C.svg', '{"name":"Cubic Gate","itemType":"Wondrous item","rarity":"legendary","description":"This cube is 3 inches across and radiates palpable magical energy. The six sides of the cube are each keyed to a different plane of existence, one of which is the Material Plane. The other sides are linked to planes determined by the GM.\n\nYou can use an action to press one side of the cube to cast the _gate_ spell with it, opening a portal to the plane keyed to that side. Alternatively, if you use an action to press one side twice, you can cast the _plane shift_ spell (save DC 17) with the cube and transport the targets to the plane keyed to that side.\n\nThe cube has 3 charges. Each use of the cube expends 1 charge. The cube regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Dagger of Venom', '/icons/items/_mono/D.svg', '{"name":"Dagger of Venom","itemType":"Weapon","rarity":"rare","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon.\n\nYou can use an action to cause thick, black poison to coat the blade. The poison remains for 1 minute or until an attack using this weapon hits a creature. That creature must succeed on a DC 15 Constitution saving throw or take 2d10 poison damage and become poisoned for 1 minute. The dagger can''t be used this way again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"dagger"}'),
    ('Dancing Sword', '/icons/items/_mono/D.svg', '{"name":"Dancing Sword","itemType":"Weapon","rarity":"very rare","description":"You can use a bonus action to toss this magic sword into the air and speak the command word. When you do so, the sword begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of it. The sword uses your attack roll and ability score modifier to damage rolls.\n\nWhile the sword hovers, you can use a bonus action to cause it to fly up to 30 feet to another spot within 30 feet of you. As part of the same bonus action, you can cause the sword to attack one creature within 5 feet of it.\n\nAfter the hovering sword attacks for the fourth time, it flies up to 30 feet and tries to return to your hand. If you have no hand free, it falls to the ground at your feet. If the sword has no unobstructed path to you, it moves as close to you as it can and then falls to the ground. It also ceases to hover if you grasp it or move more than 30 feet away from it.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Decanter of Endless Water', '/icons/items/_mono/D.svg', '{"name":"Decanter of Endless Water","itemType":"Wondrous item","rarity":"uncommon","description":"This stoppered flask sloshes when shaken, as if it contains water. The decanter weighs 2 pounds.\n\nYou can use an action to remove the stopper and speak one of three command words, whereupon an amount of fresh water or salt water (your choice) pours out of the flask. The water stops pouring out at the start of your next turn. Choose from the following options:\n\n* \"Stream\" produces 1 gallon of water.\n* \"Fountain\" produces 5 gallons of water.\n* \"Geyser\" produces 30 gallons of water that gushes forth in a geyser 30 feet long and 1 foot wide. As a bonus action while holding the decanter, you can aim the geyser at a creature you can see within 30 feet of you. The target must succeed on a DC 13 Strength saving throw or take 1d4 bludgeoning damage and fall prone. Instead of a creature, you can target an object that isn''t being worn or carried and that weighs no more than 200 pounds. The object is either knocked over or pushed up to 15 feet away from you.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Deck of Illusions', '/icons/items/_mono/D.svg', '{"name":"Deck of Illusions","itemType":"Wondrous item","rarity":"uncommon","description":"This box contains a set of parchment cards. A full deck has 34 cards. A deck found as treasure is usually missing 1d20 - 1 cards.\n\nThe magic of the deck functions only if cards are drawn at random (you can use an altered deck of playing cards to simulate the deck). You can use an action to draw a card at random from the deck and throw it to the ground at a point within 30 feet of you.\n\nAn illusion of one or more creatures forms over the thrown card and remains until dispelled. An illusory creature appears real, of the appropriate size, and behaves as if it were a real creature except that it can do no harm. While you are within 120 feet of the illusory creature and can see it, you can use an action to move it magically anywhere within 30 feet of its card. Any physical interaction with the illusory creature reveals it to be an illusion, because objects pass through it. Someone who uses an action to visually inspect the creature identifies it as illusory with a successful DC 15 Intelligence (Investigation) check. The creature then appears translucent.\n\nThe illusion lasts until its card is moved or the illusion is dispelled. When the illusion ends, the image on its card disappears, and that card can''t be used again.\n\n| Playing Card      | Illusion                         |\n|-------------------|----------------------------------|\n| Ace of hearts     | Red dragon                       |\n| King of hearts    | Knight and four guards           |\n| Queen of hearts   | Succubus or incubus              |\n| Jack of hearts    | Druid                            |\n| Ten of hearts     | Cloud giant                      |\n| Nine of hearts    | Ettin                            |\n| Eight of hearts   | Bugbear                          |\n| Two of hearts     | Goblin                           |\n| Ace of diamonds   | Beholder                         |\n| King of diamonds  | Archmage and mage apprentice     |\n| Queen of diamonds | Night hag                        |\n| Jack of diamonds  | Assassin                         |\n| Ten of diamonds   | Fire giant                       |\n| Nine of diamonds  | Ogre mage                        |\n| Eight of diamonds | Gnoll                            |\n| Two of diamonds   | Kobold                           |\n| Ace of spades     | Lich                             |\n| King of spades    | Priest and two acolytes          |\n| Queen of spades   | Medusa                           |\n| Jack of spades    | Veteran                          |\n| Ten of spades     | Frost giant                      |\n| Nine of spades    | Troll                            |\n| Eight of spades   | Hobgoblin                        |\n| Two of spades     | Goblin                           |\n| Ace of clubs      | Iron golem                       |\n| King of clubs     | Bandit captain and three bandits |\n| Queen of clubs    | Erinyes                          |\n| Jack of clubs     | Berserker                        |\n| Ten of clubs      | Hill giant                       |\n| Nine of clubs     | Ogre                             |\n| Eight of clubs    | Orc                              |\n| Two of clubs      | Kobold                           |\n| Jokers (2)        | You (the deck''s owner)           |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Deck of Many Things', '/icons/items/_mono/D.svg', '{"name":"Deck of Many Things","itemType":"Wondrous item","rarity":"legendary","description":"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum. Most (75 percent) of these decks have only thirteen cards, but the rest have twenty-two.\n\nBefore you draw a card, you must declare how many cards you intend to draw and then draw them randomly (you can use an altered deck of playing cards to simulate the deck). Any cards drawn in excess of this number have no effect. Otherwise, as soon as you draw a card from the deck, its magic takes effect. You must draw each card no more than 1 hour after the previous draw. If you fail to draw the chosen number, the remaining number of cards fly from the deck on their own and take effect all at once.\n\nOnce a card is drawn, it fades from existence. Unless the card is the Fool or the Jester, the card reappears in the deck, making it possible to draw the same card twice.\n\n| Playing Card       | Card        |\n|--------------------|-------------|\n| Ace of diamonds    | Vizier\\*    |\n| King of diamonds   | Sun         |\n| Queen of diamonds  | Moon        |\n| Jack of diamonds   | Star        |\n| Two of diamonds    | Comet\\*     |\n| Ace of hearts      | The Fates\\* |\n| King of hearts     | Throne      |\n| Queen of hearts    | Key         |\n| Jack of hearts     | Knight      |\n| Two of hearts      | Gem\\*       |\n| Ace of clubs       | Talons\\*    |\n| King of clubs      | The Void    |\n| Queen of clubs     | Flames      |\n| Jack of clubs      | Skull       |\n| Two of clubs       | Idiot\\*     |\n| Ace of spades      | Donjon\\*    |\n| King of spades     | Ruin        |\n| Queen of spades    | Euryale     |\n| Jack of spades     | Rogue       |\n| Two of spades      | Balance\\*   |\n| Joker (with TM)    | Fool\\*      |\n| Joker (without TM) | Jester      |\n\n\\*Found only in a deck with twenty-two cards\n\n**_Balance_**. Your mind suffers a wrenching alteration, causing your alignment to change. Lawful becomes chaotic, good becomes evil, and vice versa. If you are true neutral or unaligned, this card has no effect on you.\n\n**_Comet_**. If you single-handedly defeat the next hostile monster or group of monsters you encounter, you gain experience points enough to gain one level. Otherwise, this card has no effect.\n\n**_Donjon_**. You disappear and become entombed in a state of suspended animation in an extradimensional sphere. Everything you were wearing and carrying stays behind in the space you occupied when you disappeared. You remain imprisoned until you are found and removed from the sphere. You can''t be located by any divination magic, but a _wish_ spell can reveal the location of your prison. You draw no more cards.\n\n**_Euryale_**. The card''s medusa-like visage curses you. You take a -2 penalty on saving throws while cursed in this way. Only a god or the magic of The Fates card can end this curse.\n\n**_The Fates_**. Reality''s fabric unravels and spins anew, allowing you to avoid or erase one event as if it never happened. You can use the card''s magic as soon as you draw the card or at any other time before you die.\n\n**_Flames_**. A powerful devil becomes your enemy. The devil seeks your ruin and plagues your life, savoring your suffering before attempting to slay you. This enmity lasts until either you or the devil dies.\n\n**_Fool_**. You lose 10,000 XP, discard this card, and draw from the deck again, counting both draws as one of your declared draws. If losing that much XP would cause you to lose a level, you instead lose an amount that leaves you with just enough XP to keep your level.\n\n**_Gem_**. Twenty-five pieces of jewelry worth 2,000 gp each or fifty gems worth 1,000 gp each appear at your feet.\n\n**_Idiot_**. Permanently reduce your Intelligence by 1d4 + 1 (to a minimum score of 1). You can draw one additional card beyond your declared draws.\n\n**_Jester_**. You gain 10,000 XP, or you can draw two additional cards beyond your declared draws.\n\n**_Key_**. A rare or rarer magic weapon with which you are proficient appears in your hands. The GM chooses the weapon.\n\n**_Knight_**. You gain the service of a 4th-level fighter who appears in a space you choose within 30 feet of you. The fighter is of the same race as you and serves you loyally until death, believing the fates have drawn him or her to you. You control this character.\n\n**_Moon_**. You are granted the ability to cast the _wish_ spell 1d3 times.\n\n**_Rogue_**. A nonplayer character of the GM''s choice becomes hostile toward you. The identity of your new enemy isn''t known until the NPC or someone else reveals it. Nothing less than a _wish_ spell or divine intervention can end the NPC''s hostility toward you.\n\n**_Ruin_**. All forms of wealth that you carry or own, other than magic items, are lost to you. Portable property vanishes. Businesses, buildings, and land you own are lost in a way that alters reality the least. Any documentation that proves you should own something lost to this card also disappears.\n\n**_Skull_**. You summon an avatar of death-a ghostly humanoid skeleton clad in a tattered black robe and carrying a spectral scythe. It appears in a space of the GM''s choice within 10 feet of you and attacks you, warning all others that you must win the battle alone. The avatar fights until you die or it drops to 0 hit points, whereupon it disappears. If anyone tries to help you, the helper summons its own avatar of death. A creature slain by an avatar of death can''t be restored to life.\n\n**_Star_**. Increase one of your ability scores by 2. The score can exceed 20 but can''t exceed 24.\n\n**_Sun_**. You gain 50,000 XP, and a wondrous item (which the GM determines randomly) appears in your hands.\n\n**_Talons_**. Every magic item you wear or carry disintegrates. Artifacts in your possession aren''t destroyed but do vanish.\n\n**_Throne_**. You gain proficiency in the Persuasion skill, and you double your proficiency bonus on checks made with that skill. In addition, you gain rightful ownership of a small keep somewhere in the world. However, the keep is currently in the hands of monsters, which you must clear out before you can claim the keep as yours.\n\n**_Vizier_**. At any time you choose within one year of drawing this card, you can ask a question in meditation and mentally receive a truthful answer to that question. Besides information, the answer helps you solve a puzzling problem or other dilemma. In other words, the knowledge comes with wisdom on how to apply it.\n\n**_The Void_**. This black card spells disaster. Your soul is drawn from your body and contained in an object in a place of the GM''s choice. One or more powerful beings guard the place. While your soul is trapped in this way, your body is incapacitated. A wish spell can''t restore your soul, but the spell reveals the location of the object that holds it. You draw no more cards.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Defender', '/icons/items/_mono/D.svg', '{"name":"Defender","itemType":"Weapon","rarity":"legendary","description":"You gain a +3 bonus to attack and damage rolls made with this magic weapon.\n\nThe first time you attack with the sword on each of your turns, you can transfer some or all of the sword''s bonus to your Armor Class, instead of using the bonus on any attacks that turn. For example, you could reduce the bonus to your attack and damage rolls to +1 and gain a +2 bonus to AC. The adjusted bonuses remain in effect until the start of your next turn, although you must hold the sword to gain a bonus to AC from it.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Demon Armor', '/icons/items/_mono/D.svg', '{"name":"Demon Armor","itemType":"Armor","rarity":"very rare","description":"While wearing this armor, you gain a +1 bonus to AC, and you can understand and speak Abyssal. In addition, the armor''s clawed gauntlets turn unarmed strikes with your hands into magic weapons that deal slashing damage, with a +1 bonus to attack rolls and damage rolls and a damage die of 1d8.\n\n**_Curse_**. Once you don this cursed armor, you can''t doff it unless you are targeted by the _remove curse_ spell or similar magic. While wearing the armor, you have disadvantage on attack rolls against demons and on saving throws against their spells and special abilities.","source":"SRD 5.1, CC-BY-4.0","baseType":"plate","attunement":true}'),
    ('Dimensional Shackles', '/icons/items/_mono/D.svg', '{"name":"Dimensional Shackles","itemType":"Wondrous item","rarity":"rare","description":"You can use an action to place these shackles on an incapacitated creature. The shackles adjust to fit a creature of Small to Large size. In addition to serving as mundane manacles, the shackles prevent a creature bound by them from using any method of extradimensional movement, including teleportation or travel to a different plane of existence. They don''t prevent the creature from passing through an interdimensional portal.\n\nYou and any creature you designate when you use the shackles can use an action to remove them. Once every 30 days, the bound creature can make a DC 30 Strength (Athletics) check. On a success, the creature breaks free and destroys the shackles.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Dragon Scale Mail', '/icons/items/_mono/D.svg', '{"name":"Dragon Scale Mail","itemType":"Armor","rarity":"very rare","description":"Dragon scale mail is made of the scales of one kind of dragon. Sometimes dragons collect their cast-off scales and gift them to humanoids. Other times, hunters carefully skin and preserve the hide of a dead dragon. In either case, dragon scale mail is highly valued.\n\nWhile wearing this armor, you gain a +1 bonus to AC, you have advantage on saving throws against the Frightful Presence and breath weapons of dragons, and you have resistance to one damage type that is determined by the kind of dragon that provided the scales (see the table).\n\nAdditionally, you can focus your senses as an action to magically discern the distance and direction to the closest dragon within 30 miles of you that is of the same type as the armor. This special action can''t be used again until the next dawn.\n\n| Dragon | Resistance |\n|--------|------------|\n| Black  | Acid       |\n| Blue   | Lightning  |\n| Brass  | Fire       |\n| Bronze | Lightning  |\n| Copper | Acid       |\n| Gold   | Fire       |\n| Green  | Poison     |\n| Red    | Fire       |\n| Silver | Cold       |\n| White  | Cold       |","source":"SRD 5.1, CC-BY-4.0","baseType":"scale mail","attunement":true}'),
    ('Dragon Slayer', '/icons/items/_mono/D.svg', '{"name":"Dragon Slayer","itemType":"Weapon","rarity":"rare","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon.\n\nWhen you hit a dragon with this weapon, the dragon takes an extra 3d6 damage of the weapon''s type. For the purpose of this weapon, \"dragon\" refers to any creature with the dragon type, including dragon turtles and wyverns.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword"}'),
    ('Dust of Disappearance', '/icons/items/_mono/D.svg', '{"name":"Dust of Disappearance","itemType":"Wondrous item","rarity":"uncommon","description":"Found in a small packet, this powder resembles very fine sand. There is enough of it for one use. When you use an action to throw the dust into the air, you and each creature and object within 10 feet of you become invisible for 2d4 minutes. The duration is the same for all subjects, and the dust is consumed when its magic takes effect. If a creature affected by the dust attacks or casts a spell, the invisibility ends for that creature.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Dust of Dryness', '/icons/items/_mono/D.svg', '{"name":"Dust of Dryness","itemType":"Wondrous item","rarity":"uncommon","description":"This small packet contains 1d6 + 4 pinches of dust. You can use an action to sprinkle a pinch of it over water. The dust turns a cube of water 15 feet on a side into one marble-sized pellet, which floats or rests near where the dust was sprinkled. The pellet''s weight is negligible.\n\nSomeone can use an action to smash the pellet against a hard surface, causing the pellet to shatter and release the water the dust absorbed. Doing so ends that pellet''s magic.\n\nAn elemental composed mostly of water that is exposed to a pinch of the dust must make a DC 13 Constitution saving throw, taking 10d6 necrotic damage on a failed save, or half as much damage on a successful one.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Dust of Sneezing and Choking', '/icons/items/_mono/D.svg', '{"name":"Dust of Sneezing and Choking","itemType":"Wondrous item","rarity":"uncommon","description":"Found in a small container, this powder resembles very fine sand. It appears to be _dust of disappearance_, and an _identify_ spell reveals it to be such. There is enough of it for one use.\n\nWhen you use an action to throw a handful of the dust into the air, you and each creature that needs to breathe within 30 feet of you must succeed on a DC 15 Constitution saving throw or become unable to breathe, while sneezing uncontrollably. A creature affected in this way is incapacitated and suffocating. As long as it is conscious, a creature can repeat the saving throw at the end of each of its turns, ending the effect on it on a success. The _lesser restoration_ spell can also end the effect on a creature.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Dwarven Plate', '/icons/items/_mono/D.svg', '{"name":"Dwarven Plate","itemType":"Armor","rarity":"very rare","description":"While wearing this armor, you gain a +2 bonus to AC. In addition, if an effect moves you against your will along the ground, you can use your reaction to reduce the distance you are moved by up to 10 feet.","source":"SRD 5.1, CC-BY-4.0","baseType":"plate"}'),
    ('Dwarven Thrower', '/icons/items/_mono/D.svg', '{"name":"Dwarven Thrower","itemType":"Weapon","rarity":"very rare","description":"You gain a +3 bonus to attack and damage rolls made with this magic weapon. It has the thrown property with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged attack using this weapon, it deals an extra 1d8 damage or, if the target is a giant, 2d8 damage. Immediately after the attack, the weapon flies back to your hand.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"warhammer","attunement":true,"attunementNote":"by a dwarf"}'),
    ('Efficient Quiver', '/icons/items/_mono/E.svg', '{"name":"Efficient Quiver","itemType":"Wondrous item","rarity":"uncommon","description":"Each of the quiver''s three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds. The shortest compartment can hold up to sixty arrows, bolts, or similar objects. The midsize compartment holds up to eighteen javelins or similar objects. The longest compartment holds up to six long objects, such as bows, quarterstaffs, or spears.\n\nYou can draw any item the quiver contains as if doing so from a regular quiver or scabbard.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Efreeti Bottle', '/icons/items/_mono/E.svg', '{"name":"Efreeti Bottle","itemType":"Wondrous item","rarity":"very rare","description":"This painted brass bottle weighs 1 pound. When you use an action to remove the stopper, a cloud of thick smoke flows out of the bottle. At the end of your turn, the smoke disappears with a flash of harmless fire, and an efreeti appears in an unoccupied space within 30 feet of you.\n\nThe first time the bottle is opened, the GM rolls to determine what happens.\n\n| d100   | Effect                                                                                                                                                                                                                                                                                                                                                 |\n|--------|--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n| 01-10  | The efreeti attacks you. After fighting for 5 rounds, the efreeti disappears, and the bottle loses its magic.                                                                                                                                                                                                                                          |\n| 11-90  | The efreeti serves you for 1 hour, doing as you command. Then the efreeti returns to the bottle, and a new stopper contains it. The stopper can''t be removed for 24 hours. The next two times the bottle is opened, the same effect occurs. If the bottle is opened a fourth time, the efreeti escapes and disappears, and the bottle loses its magic. |\n| 91-100 | The efreeti can cast the wish spell three times for you. It disappears when it grants the final wish or after 1 hour, and the bottle loses its magic.                                                                                                                                                                                                  |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Elemental Gem', '/icons/items/_mono/E.svg', '{"name":"Elemental Gem","itemType":"Wondrous item","rarity":"uncommon","description":"This gem contains a mote of elemental energy. When you use an action to break the gem, an elemental is summoned as if you had cast the _conjure elemental_ spell, and the gem''s magic is lost. The type of gem determines the elemental summoned by the spell.\n\n| Gem            | Summoned Elemental |\n|----------------|--------------------|\n| Blue sapphire  | Air elemental      |\n| Yellow diamond | Earth elemental    |\n| Red corundum   | Fire elemental     |\n| Emerald        | Water elemental    |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Elven Chain', '/icons/items/_mono/E.svg', '{"name":"Elven Chain","itemType":"Armor","rarity":"rare","description":"You gain a +1 bonus to AC while you wear this armor. You are considered proficient with this armor even if you lack proficiency with medium armor.","source":"SRD 5.1, CC-BY-4.0","baseType":"chain shirt"}'),
    ('Eversmoking Bottle', '/icons/items/_mono/E.svg', '{"name":"Eversmoking Bottle","itemType":"Wondrous item","rarity":"uncommon","description":"Smoke leaks from the lead-stoppered mouth of this brass bottle, which weighs 1 pound. When you use an action to remove the stopper, a cloud of thick smoke pours out in a 60-foot radius from the bottle. The cloud''s area is heavily obscured. Each minute the bottle remains open and within the cloud, the radius increases by 10 feet until it reaches its maximum radius of 120 feet.\n\nThe cloud persists as long as the bottle is open. Closing the bottle requires you to speak its command word as an action. Once the bottle is closed, the cloud disperses after 10 minutes. A moderate wind (11 to 20 miles per hour) can also disperse the smoke after 1 minute, and a strong wind (21 or more miles per hour) can do so after 1 round.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Eyes of Charming', '/icons/items/_mono/E.svg', '{"name":"Eyes of Charming","itemType":"Wondrous item","rarity":"uncommon","description":"These crystal lenses fit over the eyes. They have 3 charges. While wearing them, you can expend 1 charge as an action to cast the _charm person_ spell (save DC 13) on a humanoid within 30 feet of you, provided that you and the target can see each other. The lenses regain all expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Eyes of Minute Seeing', '/icons/items/_mono/E.svg', '{"name":"Eyes of Minute Seeing","itemType":"Wondrous item","rarity":"uncommon","description":"These crystal lenses fit over the eyes. While wearing them, you can see much better than normal out to a range of 1 foot. You have advantage on Intelligence (Investigation) checks that rely on sight while searching an area or studying an object within that range.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Eyes of the Eagle', '/icons/items/_mono/E.svg', '{"name":"Eyes of the Eagle","itemType":"Wondrous item","rarity":"uncommon","description":"These crystal lenses fit over the eyes. While wearing them, you have advantage on Wisdom (Perception) checks that rely on sight. In conditions of clear visibility, you can make out details of even extremely distant creatures and objects as small as 2 feet across.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Feather Token', '/icons/items/_mono/F.svg', '{"name":"Feather Token","itemType":"Wondrous item","rarity":"rare","description":"This tiny object looks like a feather. Different types of feather tokens exist, each with a different single* use effect. The GM chooses the kind of token or determines it randomly.\n\n| d100   | Feather Token |\n|--------|---------------|\n| 01-20  | Anchor        |\n| 21-35  | Bird          |\n| 36-50  | Fan           |\n| 51-65  | Swan boat     |\n| 66-90  | Tree          |\n| 91-100  | Whip          |\n\n**_Anchor_**. You can use an action to touch the token to a boat or ship. For the next 24 hours, the vessel can''t be moved by any means. Touching the token to the vessel again ends the effect. When the effect ends, the token disappears.\n\n**_Bird_**. You can use an action to toss the token 5 feet into the air. The token disappears and an enormous, multicolored bird takes its place. The bird has the statistics of a roc, but it obeys your simple commands and can''t attack. It can carry up to 500 pounds while flying at its maximum speed (16 miles an hour for a maximum of 144 miles per day, with a one-hour rest for every 3 hours of flying), or 1,000 pounds at half that speed. The bird disappears after flying its maximum distance for a day or if it drops to 0 hit points. You can dismiss the bird as an action.\n\n**_Fan_**. If you are on a boat or ship, you can use an action to toss the token up to 10 feet in the air. The token disappears, and a giant flapping fan takes its place. The fan floats and creates a wind strong enough to fill the sails of one ship, increasing its speed by 5 miles per hour for 8 hours. You can dismiss the fan as an action.\n\n**_Swan Boat_**. You can use an action to touch the token to a body of water at least 60 feet in diameter. The token disappears, and a 50-foot-long, 20-foot* wide boat shaped like a swan takes its place. The boat is self-propelled and moves across water at a speed of 6 miles per hour. You can use an action while on the boat to command it to move or to turn up to 90 degrees. The boat can carry up to thirty-two Medium or smaller creatures. A Large creature counts as four Medium creatures, while a Huge creature counts as nine. The boat remains for 24 hours and then disappears. You can dismiss the boat as an action.\n\n**_Tree_**. You must be outdoors to use this token. You can use an action to touch it to an unoccupied space on the ground. The token disappears, and in its place a nonmagical oak tree springs into existence. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius.\n\n**_Whip_**. You can use an action to throw the token to a point within 10 feet of you. The token disappears, and a floating whip takes its place. You can then use a bonus action to make a melee spell attack against a creature within 10 feet of the whip, with an attack bonus of +9. On a hit, the target takes 1d6 + 5 force damage.\n\nAs a bonus action on your turn, you can direct the whip to fly up to 20 feet and repeat the attack against a creature within 10 feet of it. The whip disappears after 1 hour, when you use an action to dismiss it, or when you are incapacitated or die.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Figurine of Wondrous Power', '/icons/items/_mono/F.svg', '{"name":"Figurine of Wondrous Power","itemType":"Wondrous item","rarity":"rare","description":"A _figurine of wondrous power_ is a statuette of a beast small enough to fit in a pocket. If you use an action to speak the command word and throw the figurine to a point on the ground within 60 feet of you, the figurine becomes a living creature. If the space where the creature would appear is occupied by other creatures or objects, or if there isn''t enough space for the creature, the figurine doesn''t become a creature.\n\nThe creature is friendly to you and your companions. It understands your languages and obeys your spoken commands. If you issue no commands, the creature defends itself but takes no other actions.\n\nThe creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if it drops to 0 hit points or if you use an action to speak the command word again while touching it. When the creature becomes a figurine again, its property can''t be used again until a certain amount of time has passed, as specified in the figurine''s description.\n\n**_Bronze Griffon (Rare)_**. This bronze statuette is of a griffon rampant. It can become a griffon for up to 6 hours. Once it has been used, it can''t be used again until 5 days have passed.\n\n**_Ebony Fly (Rare)_**. This ebony statuette is carved in the likeness of a horsefly. It can become a giant fly for up to 12 hours and can be ridden as a mount. Once it has been used, it can''t be used again until 2 days have passed.\n\n> ##### Giant Fly\n> **Armor Class** 11  \n> **Hit Points** 19 (3d10 + 3)  \n> **Speed** 30 ft., fly 60 ft.\n>\n> | STR     | DEX     | CON     | INT    | WIS     | CHA    |\n> |---------|---------|---------|--------|---------|--------|\n> | 14 (+2) | 13 (+1) | 13 (+1) | 2 (-4) | 10 (+0) | 3 (-4) |\n>\n> **Senses** darkvision 60 ft., passive Perception 10  \n> **Languages** -\n\n**_Golden Lions (Rare)_**. These gold statuettes of lions are always created in pairs. You can use one figurine or both simultaneously. Each can become a lion for up to 1 hour. Once a lion has been used, it can''t be used again until 7 days have passed.\n\n**_Ivory Goats (Rare)_**. These ivory statuettes of goats are always created in sets of three. Each goat looks unique and functions differently from the others. Their properties are as follows:\n\n* The _goat of traveling_ can become a Large goat with the same statistics as a riding horse. It has 24 charges, and each hour or portion thereof it spends in beast form costs 1 charge. While it has charges, you can use it as often as you wish. When it runs out of charges, it reverts to a figurine and can''t be used again until 7 days have passed, when it regains all its charges.\n* The _goat of travail_ becomes a giant goat for up to 3 hours. Once it has been used, it can''t be used again until 30 days have passed.\n* The _goat of terror_ becomes a giant goat for up to 3 hours. The goat can''t attack, but you can remove its horns and use them as weapons. One horn becomes a _+1 lance_, and the other becomes a _+2 longsword_. Removing a horn requires an action, and the weapons disappear and the horns return when the goat reverts to figurine form. In addition, the goat radiates a 30-foot-radius aura of terror while you are riding it. Any creature hostile to you that starts its turn in the aura must succeed on a DC 15 Wisdom saving throw or be frightened of the goat for 1 minute, or until the goat reverts to figurine form. The frightened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. Once it successfully saves against the effect, a creature is immune to the goat''s aura for the next 24 hours. Once the figurine has been used, it can''t be used again until 15 days have passed.\n\n**_Marble Elephant (Rare)_**. This marble statuette is about 4 inches high and long. It can become an elephant for up to 24 hours. Once it has been used, it can''t be used again until 7 days have passed.\n\n**_Obsidian Steed (Very Rare)_**. This polished obsidian horse can become a nightmare for up to 24 hours. The nightmare fights only to defend itself. Once it has been used, it can''t be used again until 5 days have passed.\n\nIf you have a good alignment, the figurine has a 10 percent chance each time you use it to ignore your orders, including a command to revert to figurine form. If you mount the nightmare while it is ignoring your orders, you and the nightmare are instantly transported to a random location on the plane of Hades, where the nightmare reverts to figurine form.\n\n**_Onyx Dog (Rare)_**. This onyx statuette of a dog can become a mastiff for up to 6 hours. The mastiff has an Intelligence of 8 and can speak Common. It also has darkvision out to a range of 60 feet and can see invisible creatures and objects within that range. Once it has been used, it can''t be used again until 7 days have passed.\n\n**_Serpentine Owl (Rare)_**. This serpentine statuette of an owl can become a giant owl for up to 8 hours. Once it has been used, it can''t be used again until 2 days have passed. The owl can telepathically communicate with you at any range if you and it are on the same plane of existence.\n\n**_Silver Raven (Uncommon)_**. This silver statuette of a raven can become a raven for up to 12 hours. Once it has been used, it can''t be used again until 2 days have passed. While in raven form, the figurine allows you to cast the _animal messenger_ spell on it at will.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Flame Tongue', '/icons/items/_mono/F.svg', '{"name":"Flame Tongue","itemType":"Weapon","rarity":"rare","description":"You can use a bonus action to speak this magic sword''s command word, causing flames to erupt from the blade. These flames shed bright light in a 40-foot radius and dim light for an additional 40 feet. While the sword is ablaze, it deals an extra 2d6 fire damage to any target it hits. The flames last until you use a bonus action to speak the command word again or until you drop or sheathe the sword.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Folding Boat', '/icons/items/_mono/F.svg', '{"name":"Folding Boat","itemType":"Wondrous item","rarity":"rare","description":"This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep. It weighs 4 pounds and floats. It can be opened to store items inside. This item also has three command words, each requiring you to use an action to speak it.\n\nOne command word causes the box to unfold into a boat 10 feet long, 4 feet wide, and 2 feet deep. The boat has one pair of oars, an anchor, a mast, and a lateen sail. The boat can hold up to four Medium creatures comfortably.\n\nThe second command word causes the box to unfold into a ship 24 feet long, 8 feet wide, and 6 feet deep. The ship has a deck, rowing seats, five sets of oars, a steering oar, an anchor, a deck cabin, and a mast with a square sail. The ship can hold fifteen Medium creatures comfortably.\n\nWhen the box becomes a vessel, its weight becomes that of a normal vessel its size, and anything that was stored in the box remains in the boat.\n\nThe third command word causes the _folding boat_ to fold back into a box, provided that no creatures are aboard. Any objects in the vessel that can''t fit inside the box remain outside the box as it folds. Any objects in the vessel that can fit inside the box do so.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Frost Brand', '/icons/items/_mono/F.svg', '{"name":"Frost Brand","itemType":"Weapon","rarity":"very rare","description":"When you hit with an attack using this magic sword, the target takes an extra 1d6 cold damage. In addition, while you hold the sword, you have resistance to fire damage.\n\nIn freezing temperatures, the blade sheds bright light in a 10-foot radius and dim light for an additional 10 feet.\n\nWhen you draw this weapon, you can extinguish all nonmagical flames within 30 feet of you. This property can be used no more than once per hour.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Gauntlets of Ogre Power', '/icons/items/_mono/G.svg', '{"name":"Gauntlets of Ogre Power","itemType":"Wondrous item","rarity":"uncommon","description":"Your Strength score is 19 while you wear these gauntlets. They have no effect on you if your Strength is already 19 or higher.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Gem of Brightness', '/icons/items/_mono/G.svg', '{"name":"Gem of Brightness","itemType":"Wondrous item","rarity":"uncommon","description":"This prism has 50 charges. While you are holding it, you can use an action to speak one of three command words to cause one of the following effects:\n\n* The first command word causes the gem to shed bright light in a 30-foot radius and dim light for an additional 30 feet. This effect doesn''t expend a charge. It lasts until you use a bonus action to repeat the command word or until you use another function of the gem.\n* The second command word expends 1 charge and causes the gem to fire a brilliant beam of light at one creature you can see within 60 feet of you. The creature must succeed on a DC 15 Constitution saving throw or become blinded for 1 minute. The creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n* The third command word expends 5 charges and causes the gem to flare with blinding light in a 30* foot cone originating from it. Each creature in the cone must make a saving throw as if struck by the beam created with the second command word.\n\nWhen all of the gem''s charges are expended, the gem becomes a nonmagical jewel worth 50 gp.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Gem of Seeing', '/icons/items/_mono/G.svg', '{"name":"Gem of Seeing","itemType":"Wondrous item","rarity":"rare","description":"This gem has 3 charges. As an action, you can speak the gem''s command word and expend 1 charge. For the next 10 minutes, you have truesight out to 120 feet when you peer through the gem.\n\nThe gem regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Giant Slayer', '/icons/items/_mono/G.svg', '{"name":"Giant Slayer","itemType":"Weapon","rarity":"rare","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon.\n\nWhen you hit a giant with it, the giant takes an extra 2d6 damage of the weapon''s type and must succeed on a DC 15 Strength saving throw or fall prone. For the purpose of this weapon, \"giant\" refers to any creature with the giant type, including ettins and trolls.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any axe or sword"}'),
    ('Glamoured Studded Leather', '/icons/items/_mono/G.svg', '{"name":"Glamoured Studded Leather","itemType":"Armor","rarity":"rare","description":"While wearing this armor, you gain a +1 bonus to AC. You can also use a bonus action to speak the armor''s command word and cause the armor to assume the appearance of a normal set of clothing or some other kind of armor. You decide what it looks like, including color, style, and accessories, but the armor retains its normal bulk and weight. The illusory appearance lasts until you use this property again or remove the armor.","source":"SRD 5.1, CC-BY-4.0","baseType":"studded leather"}'),
    ('Gloves of Missile Snaring', '/icons/items/_mono/G.svg', '{"name":"Gloves of Missile Snaring","itemType":"Wondrous item","rarity":"uncommon","description":"These gloves seem to almost meld into your hands when you don them. When a ranged weapon attack hits you while you''re wearing them, you can use your reaction to reduce the damage by 1d10 + your Dexterity modifier, provided that you have a free hand. If you reduce the damage to 0, you can catch the missile if it is small enough for you to hold in that hand.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Gloves of Swimming and Climbing', '/icons/items/_mono/G.svg', '{"name":"Gloves of Swimming and Climbing","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing these gloves, climbing and swimming don''t cost you extra movement, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Goggles of Night', '/icons/items/_mono/G.svg', '{"name":"Goggles of Night","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing these dark lenses, you have darkvision out to a range of 60 feet. If you already have darkvision, wearing the goggles increases its range by 60 feet.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Hammer of Thunderbolts', '/icons/items/_mono/H.svg', '{"name":"Hammer of Thunderbolts","itemType":"Weapon","rarity":"legendary","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon.\n\n**_Giant''s Bane (Requires Attunement)_**. You must be wearing a _belt of giant strength_ (any variety) and _gauntlets of ogre power_ to attune to this weapon. The attunement ends if you take off either of those items. While you are attuned to this weapon and holding it, your Strength score increases by 4 and can exceed 20, but not 30. When you roll a 20 on an attack roll made with this weapon against a giant, the giant must succeed on a DC 17 Constitution saving throw or die.\n\nThe hammer also has 5 charges. While attuned to it, you can expend 1 charge and make a ranged weapon attack with the hammer, hurling it as if it had the thrown property with a normal range of 20 feet and a long range of 60 feet. If the attack hits, the hammer unleashes a thunderclap audible out to 300 feet. The target and every creature within 30 feet of it must succeed on a DC 17 Constitution saving throw or be stunned until the end of your next turn. The hammer regains 1d4 + 1 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"maul"}'),
    ('Handy Haversack', '/icons/items/_mono/H.svg', '{"name":"Handy Haversack","itemType":"Wondrous item","rarity":"rare","description":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 20 pounds of material, not exceeding a volume of 2 cubic feet. The large central pouch can hold up to 8 cubic feet or 80 pounds of material. The backpack always weighs 5 pounds, regardless of its contents.\n\nPlacing an object in the haversack follows the normal rules for interacting with objects. Retrieving an item from the haversack requires you to use an action. When you reach into the haversack for a specific item, the item is always magically on top.\n\nThe haversack has a few limitations. If it is overloaded, or if a sharp object pierces it or tears it, the haversack ruptures and is destroyed. If the haversack is destroyed, its contents are lost forever, although an artifact always turns up again somewhere. If the haversack is turned inside out, its contents spill forth, unharmed, and the haversack must be put right before it can be used again. If a breathing creature is placed within the haversack, the creature can survive for up to 10 minutes, after which time it begins to suffocate.\n\nPlacing the haversack inside an extradimensional space created by a _bag of holding_, _portable hole_, or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can''t be reopened.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Hat of Disguise', '/icons/items/_mono/H.svg', '{"name":"Hat of Disguise","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this hat, you can use an action to cast the _disguise self_ spell from it at will. The spell ends if the hat is removed.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Headband of Intellect', '/icons/items/_mono/H.svg', '{"name":"Headband of Intellect","itemType":"Wondrous item","rarity":"uncommon","description":"Your Intelligence score is 19 while you wear this headband. It has no effect on you if your Intelligence is already 19 or higher.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Helm of Brilliance', '/icons/items/_mono/H.svg', '{"name":"Helm of Brilliance","itemType":"Wondrous item","rarity":"very rare","description":"This dazzling helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic.\n\nYou gain the following benefits while wearing it:\n\n* You can use an action to cast one of the following spells (save DC 18), using one of the helm''s gems of the specified type as a component: _daylight_ (opal), _fireball_ (fire opal), _prismatic spray_ (diamond), or _wall of fire_ (ruby). The gem is destroyed when the spell is cast and disappears from the helm.\n* As long as it has at least one diamond, the helm emits dim light in a 30-foot radius when at least one undead is within that area. Any undead that starts its turn in that area takes 1d6 radiant damage.\n* As long as the helm has at least one ruby, you have resistance to fire damage.\n* As long as the helm has at least one fire opal, you can use an action and speak a command word to cause one weapon you are holding to burst into flames. The flames emit bright light in a 10-foot radius and dim light for an additional 10 feet. The flames are harmless to you and the weapon. When you hit with an attack using the blazing weapon, the target takes an extra 1d6 fire damage. The flames last until you use a bonus action to speak the command word again or until you drop or stow the weapon.\n\nRoll a d20 if you are wearing the helm and take fire damage as a result of failing a saving throw against a spell. On a roll of 1, the helm emits beams of light from its remaining gems. Each creature within 60 feet of the helm other than you must succeed on a DC 17 Dexterity saving throw or be struck by a beam, taking radiant damage equal to the number of gems in the helm. The helm and its gems are then destroyed.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Helm of Comprehending Languages', '/icons/items/_mono/H.svg', '{"name":"Helm of Comprehending Languages","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this helm, you can use an action to cast the _comprehend languages_ spell from it at will.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Helm of Telepathy', '/icons/items/_mono/H.svg', '{"name":"Helm of Telepathy","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this helm, you can use an action to cast the _detect thoughts_ spell (save DC 13) from it. As long as you maintain concentration on the spell, you can use a bonus action to send a telepathic message to a creature you are focused on. It can reply-using a bonus action to do so-while your focus on it continues.\n\nWhile focusing on a creature with _detect thoughts_, you can use an action to cast the _suggestion_ spell (save DC 13) from the helm on that creature. Once used, the _suggestion_ property can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Helm of Teleportation', '/icons/items/_mono/H.svg', '{"name":"Helm of Teleportation","itemType":"Wondrous item","rarity":"rare","description":"This helm has 3 charges. While wearing it, you can use an action and expend 1 charge to cast the _teleport_ spell from it. The helm regains 1d3\n\nexpended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Holy Avenger', '/icons/items/_mono/H.svg', '{"name":"Holy Avenger","itemType":"Weapon","rarity":"legendary","description":"You gain a +3 bonus to attack and damage rolls made with this magic weapon. When you hit a fiend or an undead with it, that creature takes an extra 2d10 radiant damage.\n\nWhile you hold the drawn sword, it creates an aura in a 10-foot radius around you. You and all creatures friendly to you in the aura have advantage on saving throws against spells and other magical effects. If you have 17 or more levels in the paladin class, the radius of the aura increases to 30 feet.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true,"attunementNote":"by a paladin"}'),
    ('Horn of Blasting', '/icons/items/_mono/H.svg', '{"name":"Horn of Blasting","itemType":"Wondrous item","rarity":"rare","description":"You can use an action to speak the horn''s command word and then blow the horn, which emits a thunderous blast in a 30-foot cone that is audible 600 feet away. Each creature in the cone must make a DC 15 Constitution saving throw. On a failed save, a creature takes 5d6 thunder damage and is deafened for 1 minute. On a successful save, a creature takes half as much damage and isn''t deafened. Creatures and objects made of glass or crystal have disadvantage on the saving throw and take 10d6 thunder damage instead of 5d6.\n\nEach use of the horn''s magic has a 20 percent chance of causing the horn to explode. The explosion deals 10d6 fire damage to the blower and destroys the horn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Horn of Valhalla', '/icons/items/_mono/H.svg', '{"name":"Horn of Valhalla","itemType":"Wondrous item","rarity":"rare","description":"You can use an action to blow this horn. In response, warrior spirits from the Valhalla appear within 60 feet of you. They use the statistics of a berserker. They return to Valhalla after 1 hour or when they drop to 0 hit points. Once you use the horn, it can''t be used again until 7 days have passed.\n\nFour types of _horn of Valhalla_ are known to exist, each made of a different metal. The horn''s type determines how many berserkers answer its summons, as well as the requirement for its use. The GM chooses the horn''s type or determines it randomly.\n\n| d100   | Horn Type | Berserkers Summoned | Requirement                          |\n|--------|-----------|---------------------|--------------------------------------|\n| 01-40  | Silver    | 2d4 + 2             | None                                 |\n| 41-75  | Brass     | 3d4 + 3             | Proficiency with all simple weapons  |\n| 76-90  | Bronze    | 4d4 + 4             | Proficiency with all medium armor    |\n| 91-00  | Iron      | 5d4 + 5             | Proficiency with all martial weapons |\n\nIf you blow the horn without meeting its requirement, the summoned berserkers attack you. If you meet the requirement, they are friendly to you and your companions and follow your commands.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Horseshoes of a Zephyr', '/icons/items/_mono/H.svg', '{"name":"Horseshoes of a Zephyr","itemType":"Wondrous item","rarity":"very rare","description":"These iron horseshoes come in a set of four. While all four shoes are affixed to the hooves of a horse or similar creature, they allow the creature to move normally while floating 4 inches above the ground. This effect means the creature can cross or stand above nonsolid or unstable surfaces, such as water or lava. The creature leaves no tracks and ignores difficult terrain. In addition, the creature can move at normal speed for up to 12 hours a day without suffering exhaustion from a forced march.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Horseshoes of Speed', '/icons/items/_mono/H.svg', '{"name":"Horseshoes of Speed","itemType":"Wondrous item","rarity":"rare","description":"These iron horseshoes come in a set of four. While all four shoes are affixed to the hooves of a horse or similar creature, they increase the creature''s walking speed by 30 feet.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Immovable Rod', '/icons/items/_mono/I.svg', '{"name":"Immovable Rod","itemType":"Rod","rarity":"uncommon","description":"This flat iron rod has a button on one end. You can use an action to press the button, which causes the rod to become magically fixed in place. Until you or another creature uses an action to push the button again, the rod doesn''t move, even if it is defying gravity. The rod can hold up to 8,000 pounds of weight. More weight causes the rod to deactivate and fall. A creature can use an action to make a DC 30 Strength check, moving the fixed rod up to 10 feet on a success.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Instant Fortress', '/icons/items/_mono/I.svg', '{"name":"Instant Fortress","itemType":"Wondrous item","rarity":"rare","description":"You can use an action to place this 1-inch metal cube on the ground and speak its command word. The cube rapidly grows into a fortress that remains until you use an action to speak the command word that dismisses it, which works only if the fortress is empty.\n\nThe fortress is a square tower, 20 feet on a side and 30 feet high, with arrow slits on all sides and a battlement atop it. Its interior is divided into two floors, with a ladder running along one wall to connect them. The ladder ends at a trapdoor leading to the roof. When activated, the tower has a small door on the side facing you. The door opens only at your command, which you can speak as a bonus action. It is immune to the _knock_ spell and similar magic, such as that of a _chime of opening_.\n\nEach creature in the area where the fortress appears must make a DC 15 Dexterity saving throw, taking 10d10 bludgeoning damage on a failed save, or half as much damage on a successful one. In either case, the creature is pushed to an unoccupied space outside but next to the fortress. Objects in the area that aren''t being worn or carried take this damage and are pushed automatically.\n\nThe tower is made of adamantine, and its magic prevents it from being tipped over. The roof, the door, and the walls each have 100 hit points,\n\nimmunity to damage from nonmagical weapons excluding siege weapons, and resistance to all other damage. Only a _wish_ spell can repair the fortress (this use of the spell counts as replicating a spell of 8th level or lower). Each casting of _wish_ causes the roof, the door, or one wall to regain 50 hit points.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Ioun Stone', '/icons/items/_mono/I.svg', '{"name":"Ioun Stone","itemType":"Wondrous item","rarity":"rare","description":"An _Ioun stone_ is named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of _Ioun stone_ exist, each type a distinct combination of shape and color.\n\nWhen you use an action to toss one of these stones into the air, the stone orbits your head at a distance of 1d3 feet and confers a benefit to you. Thereafter, another creature must use an action to grasp or net the stone to separate it from you, either by making a successful attack roll against AC 24 or a successful DC 24 Dexterity (Acrobatics) check. You can use an action to seize and stow the stone, ending its effect.\n\nA stone has AC 24, 10 hit points, and resistance to all damage. It is considered to be an object that is being worn while it orbits your head.\n\n**_Absorption (Very Rare)_**. While this pale lavender ellipsoid orbits your head, you can use your reaction to cancel a spell of 4th level or lower cast by a creature you can see and targeting only you.\n\nOnce the stone has canceled 20 levels of spells, it burns out and turns dull gray, losing its magic. If you are targeted by a spell whose level is higher than the number of spell levels the stone has left, the stone can''t cancel it.\n\n**_Agility (Very Rare)_**. Your Dexterity score increases by 2, to a maximum of 20, while this deep red sphere orbits your head.\n\n**_Awareness (Rare)_**. You can''t be surprised while this dark blue rhomboid orbits your head.\n\n**_Fortitude (Very Rare)_**. Your Constitution score increases by 2, to a maximum of 20, while this pink rhomboid orbits your head.\n\n**_Greater Absorption (Legendary)_**. While this marbled lavender and green ellipsoid orbits your head, you can use your reaction to cancel a spell of 8th level or lower cast by a creature you can see and targeting only you.\n\nOnce the stone has canceled 50 levels of spells, it burns out and turns dull gray, losing its magic. If you are targeted by a spell whose level is higher than the number of spell levels the stone has left, the stone can''t cancel it.\n\n**_Insight (Very Rare)_**. Your Wisdom score increases by 2, to a maximum of 20, while this incandescent blue sphere orbits your head.\n\n**_Intellect (Very Rare)_**. Your Intelligence score increases by 2, to a maximum of 20, while this marbled scarlet and blue sphere orbits your head.\n\n**_Leadership (Very Rare)_**. Your Charisma score increases by 2, to a maximum of 20, while this marbled pink and green sphere orbits your head.\n\n**_Mastery (Legendary)_**. Your proficiency bonus increases by 1 while this pale green prism orbits your head.\n\n**_Protection (Rare)_**. You gain a +1 bonus to AC while this dusty rose prism orbits your head.\n\n**_Regeneration (Legendary)_**. You regain 15 hit points at the end of each hour this pearly white spindle orbits your head, provided that you have at least 1 hit point.\n\n**_Reserve (Rare)_**. This vibrant purple prism stores spells cast into it, holding them until you use them. The stone can store up to 3 levels worth of spells at a time. When found, it contains 1d4 - 1 levels of stored spells chosen by the GM.\n\nAny creature can cast a spell of 1st through 3rd level into the stone by touching it as the spell is cast. The spell has no effect, other than to be stored in the stone. If the stone can''t hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses.\n\nWhile this stone orbits your head, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster, but is otherwise treated as if you cast the spell. The spell cast from the stone is no longer stored in it, freeing up space.\n\n**_Strength (Very Rare)_**. Your Strength score increases by 2, to a maximum of 20, while this pale blue rhomboid orbits your head.\n\n**_Sustenance (Rare)_**. You don''t need to eat or drink while this clear spindle orbits your head.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Iron Bands of Binding', '/icons/items/_mono/I.svg', '{"name":"Iron Bands of Binding","itemType":"Wondrous item","rarity":"rare","description":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound. You can use an action to speak the command word and throw the sphere at a Huge or smaller creature you can see within 60 feet of you. As the sphere moves through the air, it opens into a tangle of metal bands.\n\nMake a ranged attack roll with an attack bonus equal to your Dexterity modifier plus your proficiency bonus. On a hit, the target is restrained until you take a bonus action to speak the command word again to release it. Doing so, or missing with the attack, causes the bands to contract and become a sphere once more.\n\nA creature, including the one restrained, can use an action to make a DC 20 Strength check to break the iron bands. On a success, the item is destroyed, and the restrained creature is freed. If the check fails, any further attempts made by that creature automatically fail until 24 hours have elapsed.\n\nOnce the bands are used, they can''t be used again until the next dawn.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Iron Flask', '/icons/items/_mono/I.svg', '{"name":"Iron Flask","itemType":"Wondrous item","rarity":"legendary","description":"This iron bottle has a brass stopper. You can use an action to speak the flask''s command word, targeting a creature that you can see within 60 feet of you. If the target is native to a plane of existence other than the one you''re on, the target must succeed on a DC 17 Wisdom saving throw or be trapped in the flask. If the target has been trapped by the flask before, it has advantage on the saving throw. Once trapped, a creature remains in the flask until released. The flask can hold only one creature at a time. A creature trapped in the flask doesn''t need to breathe, eat, or drink and doesn''t age.\n\nYou can use an action to remove the flask''s stopper and release the creature the flask contains. The creature is friendly to you and your companions for 1 hour and obeys your commands for that duration. If you give no commands or give it a command that is likely to result in its death, it defends itself but otherwise takes no actions. At the end of the duration, the creature acts in accordance with its normal disposition and alignment.\n\nAn _identify_ spell reveals that a creature is inside the flask, but the only way to determine the type of creature is to open the flask. A newly discovered bottle might already contain a creature chosen by the GM or determined randomly.\n\n| d100  | Contents          |\n|-------|-------------------|\n| 1-50  | Empty             |\n| 51-54 | Demon (type 1)    |\n| 55-58 | Demon (type 2)    |\n| 59-62 | Demon (type 3)    |\n| 63-64 | Demon (type 4)    |\n| 65    | Demon (type 5)    |\n| 66    | Demon (type 6)    |\n| 67    | Deva              |\n| 68-69 | Devil (greater)   |\n| 70-73 | Devil (lesser)    |\n| 74-75 | Djinni            |\n| 76-77 | Efreeti           |\n| 78-83 | Elemental (any)   |\n| 84-86 | Invisible stalker |\n| 87-90 | Night hag         |\n| 91    | Planetar          |\n| 92-95 | Salamander        |\n| 96    | Solar             |\n| 97-99 | Succubus/incubus  |\n| 100   | Xorn              |","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Javelin of Lightning', '/icons/items/_mono/J.svg', '{"name":"Javelin of Lightning","itemType":"Weapon","rarity":"uncommon","description":"This javelin is a magic weapon. When you hurl it and speak its command word, it transforms into a bolt of lightning, forming a line 5 feet wide that extends out from you to a target within 120 feet. Each creature in the line excluding you and the target must make a DC 13 Dexterity saving throw, taking 4d6 lightning damage on a failed save, and half as much damage on a successful one. The lightning bolt turns back into a javelin when it reaches the target. Make a ranged weapon attack against the target. On a hit, the target takes damage from the javelin plus 4d6 lightning damage.\n\nThe javelin''s property can''t be used again until the next dawn. In the meantime, the javelin can still be used as a magic weapon.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"javelin"}'),
    ('Lantern of Revealing', '/icons/items/_mono/L.svg', '{"name":"Lantern of Revealing","itemType":"Wondrous item","rarity":"uncommon","description":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding bright light in a 30-foot radius and dim light for an additional 30 feet. Invisible creatures and objects are visible as long as they are in the lantern''s bright light. You can use an action to lower the hood, reducing the light to dim light in a 5* foot radius.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Luck Blade', '/icons/items/_mono/L.svg', '{"name":"Luck Blade","itemType":"Weapon","rarity":"legendary","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. While the sword is on your person, you also gain a +1 bonus to saving throws.\n\n**_Luck_**. If the sword is on your person, you can call on its luck (no action required) to reroll one attack roll, ability check, or saving throw you dislike. You must use the second roll. This property can''t be used again until the next dawn.\n\n**_Wish_**. The sword has 1d4 - 1 charges. While holding it, you can use an action to expend 1 charge and cast the _wish_ spell from it. This property can''t be used again until the next dawn. The sword loses this property if it has no charges.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Mace of Disruption', '/icons/items/_mono/M.svg', '{"name":"Mace of Disruption","itemType":"Weapon","rarity":"rare","description":"When you hit a fiend or an undead with this magic weapon, that creature takes an extra 2d6 radiant damage. If the target has 25 hit points or fewer after taking this damage, it must succeed on a DC 15 Wisdom saving throw or be destroyed. On a successful save, the creature becomes frightened of you until the end of your next turn.\n\nWhile you hold this weapon, it sheds bright light in a 20-foot radius and dim light for an additional 20 feet.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"mace","attunement":true}'),
    ('Mace of Smiting', '/icons/items/_mono/M.svg', '{"name":"Mace of Smiting","itemType":"Weapon","rarity":"rare","description":"You gain a +1 bonus to attack and damage rolls made with this magic weapon. The bonus increases to +3 when you use the mace to attack a construct.\n\nWhen you roll a 20 on an attack roll made with this weapon, the target takes an extra 2d6 bludgeoning damage, or 4d6 bludgeoning damage if it''s a construct. If a construct has 25 hit points or fewer after taking this damage, it is destroyed.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"mace"}'),
    ('Mace of Terror', '/icons/items/_mono/M.svg', '{"name":"Mace of Terror","itemType":"Weapon","rarity":"rare","description":"This magic weapon has 3 charges. While holding it, you can use an action and expend 1 charge to release a wave of terror. Each creature of your choice in a 30-foot radius extending from you must succeed on a DC 15 Wisdom saving throw or become frightened of you for 1 minute. While it is frightened in this way, a creature must spend its turns trying to move as far away from you as it can, and it can''t willingly move to a space within 30 feet of you. It also can''t take reactions. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If it has nowhere it can move, the creature can use the Dodge action. At the end of each of its turns, a creature can repeat the saving throw, ending the effect on itself on a success.\n\nThe mace regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"mace","attunement":true}'),
    ('Mantle of Spell Resistance', '/icons/items/_mono/M.svg', '{"name":"Mantle of Spell Resistance","itemType":"Wondrous item","rarity":"rare","description":"You have advantage on saving throws against spells while you wear this cloak.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Manual of Bodily Health', '/icons/items/_mono/M.svg', '{"name":"Manual of Bodily Health","itemType":"Wondrous item","rarity":"very rare","description":"This book contains health and diet tips, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Constitution score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Manual of Gainful Exercise', '/icons/items/_mono/M.svg', '{"name":"Manual of Gainful Exercise","itemType":"Wondrous item","rarity":"very rare","description":"This book describes fitness exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Strength score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Manual of Golems', '/icons/items/_mono/M.svg', '{"name":"Manual of Golems","itemType":"Wondrous item","rarity":"very rare","description":"This tome contains information and incantations necessary to make a particular type of golem. The GM chooses the type or determines it randomly. To decipher and use the manual, you must be a spellcaster with at least two 5th-level spell slots. A creature that can''t use a _manual of golems_ and attempts to read it takes 6d6 psychic damage.\n\n| d20   | Golem | Time     | Cost       |\n|-------|-------|----------|------------|\n| 1-5   | Clay  | 30 days  | 65,000 gp  |\n| 6-17  | Flesh | 60 days  | 50,000 gp  |\n| 18    | Iron  | 120 days | 100,000 gp |\n| 19-20 | Stone | 90 days  | 80,000 gp  |\n\nTo create a golem, you must spend the time shown on the table, working without interruption with the manual at hand and resting no more than 8 hours per day. You must also pay the specified cost to purchase supplies.\n\nOnce you finish creating the golem, the book is consumed in eldritch flames. The golem becomes animate when the ashes of the manual are sprinkled on it. It is under your control, and it understands and obeys your spoken commands.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Manual of Quickness of Action', '/icons/items/_mono/M.svg', '{"name":"Manual of Quickness of Action","itemType":"Wondrous item","rarity":"very rare","description":"This book contains coordination and balance exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book''s contents and practicing its guidelines, your Dexterity score increases by 2, as does your maximum for that score. The manual then loses its magic, but regains it in a century.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Marvelous Pigments', '/icons/items/_mono/M.svg', '{"name":"Marvelous Pigments","itemType":"Wondrous item","rarity":"very rare","description":"Typically found in 1d4 pots inside a fine wooden box with a brush (weighing 1 pound in total), these pigments allow you to create three-dimensional objects by painting them in two dimensions. The paint flows from the brush to form the desired object as you concentrate on its image.\n\nEach pot of paint is sufficient to cover 1,000 square feet of a surface, which lets you create inanimate objects or terrain features-such as a door, a pit, flowers, trees, cells, rooms, or weapons- that are up to 10,000 cubic feet. It takes 10 minutes to cover 100 square feet.\n\nWhen you complete the painting, the object or terrain feature depicted becomes a real, nonmagical object. Thus, painting a door on a wall creates an actual door that can be opened to whatever is beyond. Painting a pit on a floor creates a real pit, and its depth counts against the total area of objects you create.\n\nNothing created by the pigments can have a value greater than 25 gp. If you paint an object of greater value (such as a diamond or a pile of gold), the object looks authentic, but close inspection reveals it is made from paste, bone, or some other worthless material.\n\nIf you paint a form of energy such as fire or lightning, the energy appears but dissipates as soon as you complete the painting, doing no harm to anything.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Medallion of Thoughts', '/icons/items/_mono/M.svg', '{"name":"Medallion of Thoughts","itemType":"Wondrous item","rarity":"uncommon","description":"The medallion has 3 charges. While wearing it, you can use an action and expend 1 charge to cast the _detect thoughts_ spell (save DC 13) from it. The medallion regains 1d3 expended charges daily at dawn.","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Mirror of Life Trapping', '/icons/items/_mono/M.svg', '{"name":"Mirror of Life Trapping","itemType":"Wondrous item","rarity":"very rare","description":"When this 4-foot-tall mirror is viewed indirectly, its surface shows faint images of creatures. The mirror weighs 50 pounds, and it has AC 11, 10 hit points, and vulnerability to bludgeoning damage. It shatters and is destroyed when reduced to 0 hit points.\n\nIf the mirror is hanging on a vertical surface and you are within 5 feet of it, you can use an action to speak its command word and activate it. It remains activated until you use an action to speak the command word again.\n\nAny creature other than you that sees its reflection in the activated mirror while within 30 feet of it must succeed on a DC 15 Charisma saving throw or be trapped, along with anything it is wearing or carrying, in one of the mirror''s twelve extradimensional cells. This saving throw is made with advantage if the creature knows the mirror''s nature, and constructs succeed on the saving throw automatically.\n\nAn extradimensional cell is an infinite expanse filled with thick fog that reduces visibility to 10 feet. Creatures trapped in the mirror''s cells don''t age, and they don''t need to eat, drink, or sleep. A creature trapped within a cell can escape using magic that permits planar travel. Otherwise, the creature is confined to the cell until freed.\n\nIf the mirror traps a creature but its twelve extradimensional cells are already occupied, the mirror frees one trapped creature at random to accommodate the new prisoner. A freed creature appears in an unoccupied space within sight of the mirror but facing away from it. If the mirror is shattered, all creatures it contains are freed and appear in unoccupied spaces near it.\n\nWhile within 5 feet of the mirror, you can use an action to speak the name of one creature trapped in it or call out a particular cell by number. The creature named or contained in the named cell appears as an image on the mirror''s surface. You and the creature can then communicate normally.\n\nIn a similar way, you can use an action to speak a second command word and free one creature trapped in the mirror. The freed creature appears, along with its possessions, in the unoccupied space nearest to the mirror and facing away from it.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Mithral Armor', '/icons/items/_mono/M.svg', '{"name":"Mithral Armor","itemType":"Armor","rarity":"uncommon","description":"Mithral is a light, flexible metal. A mithral chain shirt or breastplate can be worn under normal clothes. If the armor normally imposes disadvantage on Dexterity (Stealth) checks or has a Strength requirement, the mithral version of the armor doesn''t.","source":"SRD 5.1, CC-BY-4.0","baseType":"medium or heavy"}'),
    ('Necklace of Adaptation', '/icons/items/_mono/N.svg', '{"name":"Necklace of Adaptation","itemType":"Wondrous item","rarity":"uncommon","description":"While wearing this necklace, you can breathe normally in any environment, and you have advantage on saving throws made against harmful gases and vapors (such as _cloudkill_ and _stinking cloud_ effects, inhaled poisons, and the breath weapons of some dragons).","source":"SRD 5.1, CC-BY-4.0","attunement":true}'),
    ('Necklace of Fireballs', '/icons/items/_mono/N.svg', '{"name":"Necklace of Fireballs","itemType":"Wondrous item","rarity":"rare","description":"This necklace has 1d6 + 3 beads hanging from it. You can use an action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a 3rd-level _fireball_ spell (save DC 15).\n\nYou can hurl multiple beads, or even the whole necklace, as one action. When you do so, increase the level of the _fireball_ by 1 for each bead beyond the first.","source":"SRD 5.1, CC-BY-4.0"}'),
    ('Necklace of Prayer Beads', '/icons/items/_mono/N.svg', '{"name":"Necklace of Prayer Beads","itemType":"Wondrous item","rarity":"rare","description":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz. It also has many nonmagical beads made from stones such as amber, bloodstone, citrine, coral, jade, pearl, or quartz. If a magic bead is removed from the necklace, that bead loses its magic.\n\nSix types of magic beads exist. The GM decides the type of each bead on the necklace or determines it randomly. A necklace can have more than one bead of the same type. To use one, you must be wearing the necklace. Each bead contains a spell that you can cast from it as a bonus action (using your spell save DC if a save is necessary). Once a magic bead''s spell is cast, that bead can''t be used again until the next dawn.\n\n| d20   | Bead of...   | Spell                                         |\n|-------|--------------|-----------------------------------------------|\n| 1-6   | Blessing     | Bless                                         |\n| 7-12  | Curing       | Cure wounds (2nd level) or lesser restoration |\n| 13-16 | Favor        | Greater restoration                           |\n| 17-18 | Smiting      | Branding smite                                |\n| 19    | Summons      | Planar ally                                   |\n| 20    | Wind walking | Wind walk                                     |","source":"SRD 5.1, CC-BY-4.0","attunement":true,"attunementNote":"by a cleric, druid, or paladin"}'),
    ('Nine Lives Stealer', '/icons/items/_mono/N.svg', '{"name":"Nine Lives Stealer","itemType":"Weapon","rarity":"very rare","description":"You gain a +2 bonus to attack and damage rolls made with this magic weapon.\n\nThe sword has 1d8 + 1 charges. If you score a critical hit against a creature that has fewer than 100 hit points, it must succeed on a DC 15 Constitution saving throw or be slain instantly as the sword tears its life force from its body (a construct or an undead is immune). The sword loses 1 charge if the creature is slain. When the sword has no charges remaining, it loses this property.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"any sword","attunement":true}'),
    ('Oathbow', '/icons/items/_mono/O.svg', '{"name":"Oathbow","itemType":"Weapon","rarity":"very rare","description":"When you nock an arrow on this bow, it whispers in Elvish, \"Swift defeat to my enemies.\" When you use this weapon to make a ranged attack, you can, as a command phrase, say, \"Swift death to you who have wronged me.\" The target of your attack becomes your sworn enemy until it dies or until dawn seven days later. You can have only one such sworn enemy at a time. When your sworn enemy dies, you can choose a new one after the next dawn.\n\nWhen you make a ranged attack roll with this weapon against your sworn enemy, you have advantage on the roll. In addition, your target gains no benefit from cover, other than total cover, and you suffer no disadvantage due to long range. If the attack hits, your sworn enemy takes an extra 3d6 piercing damage.\n\nWhile your sworn enemy lives, you have disadvantage on attack rolls with all other weapons.","source":"SRD 5.1, CC-BY-4.0","baseWeapon":"longbow","attunement":true}')
  ) as v(name, image_url, item)
  where not exists (
    select 1 from public.token_assets t
    where t.owner_id = me and t.token_type = 'item' and t.name = v.name
  );
end $$;
